/**
 * gradedRaces.ts - Graded stakes race data
 *
 * This file provides a comprehensive dataset of graded stakes races worldwide,
 * including race definitions, schedules, restrictions, and Triple Crown groupings.
 *
 * Dependencies: @/game/tracks (TRACK_BY_NAME)
 * Related files: Used throughout race scheduling and calendar systems
 */

// Canadian Grade 1 stakes races (run at Woodbine).
// Source: Wikipedia – Category:Grade 1 stakes races in Canada.
// Distances normalized to meters. dayOfYear schedules each race on the
// game's 365-day annual cycle (day 1 = Jan 1).

import { TRACK_BY_NAME } from "@/data/tracks";
import { generateUUID } from "@/core/uuid";

export type Grade = "G1" | "G2" | "G3";

export type GradedRace = {
  uuid: string; // Unique identifier for this race
  key: string;
  name: string;
  track: string; // Track name (for display)
  trackId: string; // Track UUID reference
  country?: string;
  grade: Grade;
  distance: number;
  surface: "Turf" | "Dirt" | "Synthetic";
  purse: number;
  dayOfYear: number;
  restrictions?: {
    minAge?: number;
    maxAge?: number;
    gender?:
      | "colt"
      | "filly"
      | "horse"
      | "mare"
      | "fillies"
      | "mares"
      | "colts"
      | "fillies-and-mares"
      | "colts-and-fillies";
    // Hemisphere-specific age restrictions (e.g., for Dubai races)
    minAgeNorthern?: number;
    minAgeSouthern?: number;
  };
  note?: string; // e.g. "Fillies & Mares" — display-only
  triplecrownKey?: string; // e.g. "usa-tc", "uk-tc" — groups Triple Crown legs
  bcKey?: string; // e.g. "breeders-cup" — groups BC championship races
  winAndYouInTarget?: string; // e.g. "bc-classic" - target race for automatic qualification (Win and You're In)
  requiresInvitation?: boolean; // true for invite-only races (e.g. Breeders' Cup, invitational stakes)
  inviteDaysAhead?: number; // how many days before race day to send invites (default: 30)
  dayOfYearVariance?: number; // max ±days to shift from base dayOfYear each year (default: 3)
  purseGrowthRate?: number; // annual % purse growth (default: 0.02)
  fieldSize?: number; // Real-life field size for this race (defaults to 12 if not specified)
};

/**
 * Calculate the day of the year (1-365).
 *
 * @param month - Month (1-12)
 * @param day - Day of month
 * @returns Day of the year
 */
export function doy(month: number, day: number): number {
  const cum = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
  return cum[month - 1] + day;
}

